package com.bitti06.modplayjs.engine

import android.content.Context
import android.util.Log
import org.json.JSONObject
import java.util.concurrent.atomic.AtomicReference

/**
 * Which format bridge belongs to which file extension.
 *
 * The table lives in `assets/modules/manifest.json`, generated by
 * `apps/xr/scripts/build-modules.mjs`. Reading it instead of hardcoding a
 * second map in Kotlin is deliberate: the build script already has to know
 * which package provides which extension (it is the same table that generates
 * the install bridges), and two copies would drift the moment a format moves.
 */
object ModuleCatalog {

    private const val TAG = "modplay-xr"

    private class Table(
        /** Extension without the dot, lower case. */
        val byExtension: Map<String, String>,
        /** Every installable format, in bridge path order. */
        val formats: List<String>,
    )

    private val table = AtomicReference<Table?>(null)

    fun load(context: Context): Boolean {
        if (table.get() != null) return true
        return try {
            // An installed engine catalog wins: it is the manifest that matches
            // the modules the loader will actually read.
            val json =
                EngineModules.installedManifest(context)
                    ?: context.assets
                        .open("modules/manifest.json")
                        .bufferedReader()
                        .use { it.readText() }
            val root = JSONObject(json)
            val formatsJson = root.optJSONObject("formats") ?: JSONObject()
            val byExtension = HashMap<String, String>()
            val formats = ArrayList<String>()
            for (format in formatsJson.keys()) {
                formats += format
                val extensions = formatsJson.optJSONObject(format)?.optJSONArray("extensions")
                    ?: continue
                for (i in 0 until extensions.length()) {
                    val ext = extensions.optString(i).lowercase()
                    if (ext.isNotEmpty()) byExtension[ext] = format
                }
            }
            table.set(Table(byExtension, formats))
            Log.i(TAG, "module catalog: ${formats.size} formats, ${byExtension.size} extensions")
            true
        } catch (t: Throwable) {
            Log.w(TAG, "module catalog unavailable: ${t.javaClass.simpleName}: ${t.message}")
            false
        }
    }

    /**
     * Format bridge for a file name, or null when the extension is not in the
     * table (a streamed WAV/MP3/OGG, or a module whose extension lies).
     */
    fun formatFor(fileName: String): String? {
        val ext = fileName.substringAfterLast('.', "").lowercase()
        if (ext.isEmpty()) return null
        return table.get()?.byExtension?.get(ext)
    }

    /** All installable formats; used to warm the engine at startup. */
    fun formats(): List<String> = table.get()?.formats.orEmpty()

    /** Re-read after an engine update installed a new manifest. */
    fun reload(context: Context): Boolean {
        table.set(null)
        return load(context)
    }
}
